31	    /**
32	     * Derives an owner's duplicate-detection identity key as
33	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
34	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
35	     * telephone, email or household id contributes the empty string in its position.
36	     */
37	    default String formatIdentityKey(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
42	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
43	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
44	        return telephone + "|" + email + "|" + householdId;
45	    }
46	
47	    /**
48	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
49	     * (non-null and non-blank), otherwise {@code PHONE}.
50	     */
51	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
56	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
57	    }
58	
59	    /**
60	     * Derives an owner's locality (region) from the city using a fixed city-to-region table
61	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns
62	     * {@code "UNKNOWN"} when the city is not in the table.
63	     */
64	    default String formatLocality(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
69	            case "Sydney" -> "NSW";
70	            case "Melbourne" -> "VIC";
71	            case "Brisbane" -> "QLD";
72	            default -> "UNKNOWN";
73	        };
74	    }
75	
76	    /**
77	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
78	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
79	     * tenure).
80	     */
81	    default Integer formatMembershipLevel(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        int level = 1;
86	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
87	        if (hasEmail) {
88	            level++;
89	        }
90	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
91	        if (unique) {
92	            level++;
93	        }
94	        return Math.min(level, 3);
95	    }
96	
97	    /**
98	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
99	     * digits of the registration-date year (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} when the
100	     * customer code or registration date is absent.
101	     */
102	    default String formatMembershipNumber(Owner owner) {
103	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
104	            return null;
105	        }
106	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
107	    }
108	
109	    /**
110	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
111	     */
112	    default String formatDisplayName(Owner owner) {
113	        if (owner == null) {
114	            return null;
115	        }
116	        return owner.getLastName() + ", " + owner.getFirstName();
117	    }
118	
119	    /**
120	     * Formats an owner's initials as the upper-cased first letters of the first and last
121	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
122	     */
123	    default String formatInitials(Owner owner) {
124	        if (owner == null) {
125	            return null;
126	        }
127	        return initial(owner.getFirstName()) + initial(owner.getLastName());
128	    }
129	
130	    private String initial(String name) {
131	        if (name == null || name.isEmpty()) {
132	            return "";
133	        }
134	        return Character.toUpperCase(name.charAt(0)) + ".";
135	    }
